// Core artifact types

export type ArtifactType = 
  | 'code'
  | 'text'
  | 'markdown'
  | 'html'
  | 'json'
  | 'yaml'
  | 'xml'
  | 'csv'
  | 'image'
  | 'diagram';

export interface Artifact {
  id: string;
  type: ArtifactType;
  content: string;
  title?: string;
  language?: string;
  conversationId: string;
  createdAt: Date;
  updatedAt: Date;
  version: number;
  metadata?: Record<string, unknown>;
}

export interface ArtifactVersion {
  version: number;
  content: string;
  createdAt: Date;
  metadata?: Record<string, unknown>;
}

export interface CreateArtifactRequest {
  type: ArtifactType;
  content: string;
  title?: string;
  language?: string;
  conversationId: string;
  metadata?: Record<string, unknown>;
}

export interface UpdateArtifactRequest {
  content?: string;
  title?: string;
  language?: string;
  metadata?: Record<string, unknown>;
}

export interface ArtifactQuery {
  conversationId?: string;
  type?: ArtifactType;
  limit?: number;
  offset?: number;
}

export interface ArtifactListResponse {
  artifacts: Artifact[];
  total: number;
  limit: number;
  offset: number;
}

export interface StorageStats {
  totalArtifacts: number;
  totalVersions: number;
  byType: Record<ArtifactType, number>;
  byConversation: Record<string, number>;
}

// Validation helpers
export function isValidArtifactType(type: string): type is ArtifactType {
  const validTypes: ArtifactType[] = [
    'code', 'text', 'markdown', 'html', 'json',
    'yaml', 'xml', 'csv', 'image', 'diagram'
  ];
  return validTypes.includes(type as ArtifactType);
}

export function validateCreateRequest(req: unknown): req is CreateArtifactRequest {
  if (!req || typeof req !== 'object') return false;
  const r = req as Record<string, unknown>;

  return (
    typeof r.type === 'string' &&
    isValidArtifactType(r.type) &&
    typeof r.content === 'string' &&
    typeof r.conversationId === 'string' &&
    (r.title === undefined || typeof r.title === 'string') &&
    (r.language === undefined || typeof r.language === 'string') &&
    (r.metadata === undefined || typeof r.metadata === 'object')
  );
}

export function validateUpdateRequest(req: unknown): req is UpdateArtifactRequest {
  if (!req || typeof req !== 'object') return false;
  const r = req as Record<string, unknown>;

  return (
    (r.content === undefined || typeof r.content === 'string') &&
    (r.title === undefined || typeof r.title === 'string') &&
    (r.language === undefined || typeof r.language === 'string') &&
    (r.metadata === undefined || typeof r.metadata === 'object')
  );
}
