import { v4 as uuidv4 } from 'uuid';
import {
  Artifact,
  ArtifactVersion,
  CreateArtifactRequest,
  UpdateArtifactRequest,
  ArtifactQuery,
  ArtifactListResponse,
  StorageStats,
  ArtifactType,
} from './types';
import { Config, defaultConfig } from './config';

export class ArtifactEngine {
  private artifacts: Map<string, Artifact> = new Map();
  private versions: Map<string, ArtifactVersion[]> = new Map();
  private accessOrder: string[] = [];
  private config: Config;

  constructor(config: Partial<Config> = {}) {
    this.config = { ...defaultConfig, ...config };
  }

  /**
   * Create a new artifact
   */
  create(request: CreateArtifactRequest): Artifact {
    this.enforceMaxArtifacts();

    const id = uuidv4();
    const now = new Date();

    const artifact: Artifact = {
      id,
      type: request.type,
      content: request.content,
      title: request.title,
      language: request.language,
      conversationId: request.conversationId,
      createdAt: now,
      updatedAt: now,
      version: 1,
      metadata: request.metadata,
    };

    this.artifacts.set(id, artifact);
    this.versions.set(id, [{
      version: 1,
      content: request.content,
      createdAt: now,
      metadata: request.metadata,
    }]);
    this.updateAccessOrder(id);

    return artifact;
  }

  /**
   * Get an artifact by ID
   */
  get(id: string): Artifact | undefined {
    const artifact = this.artifacts.get(id);
    if (artifact) {
      this.updateAccessOrder(id);
    }
    return artifact;
  }

  /**
   * Update an existing artifact
   */
  update(id: string, request: UpdateArtifactRequest): Artifact | undefined {
    const artifact = this.artifacts.get(id);
    if (!artifact) {
      return undefined;
    }

    const now = new Date();
    const newVersion = artifact.version + 1;

    // Update artifact
    if (request.content !== undefined) {
      artifact.content = request.content;
    }
    if (request.title !== undefined) {
      artifact.title = request.title;
    }
    if (request.language !== undefined) {
      artifact.language = request.language;
    }
    if (request.metadata !== undefined) {
      artifact.metadata = { ...artifact.metadata, ...request.metadata };
    }

    artifact.updatedAt = now;
    artifact.version = newVersion;

    // Store version history
    const versionHistory = this.versions.get(id) || [];
    versionHistory.push({
      version: newVersion,
      content: artifact.content,
      createdAt: now,
      metadata: artifact.metadata,
    });

    // Enforce max versions
    while (versionHistory.length > this.config.maxVersionsPerArtifact) {
      versionHistory.shift();
    }

    this.versions.set(id, versionHistory);
    this.updateAccessOrder(id);

    return artifact;
  }

  /**
   * Delete an artifact
   */
  delete(id: string): boolean {
    const existed = this.artifacts.has(id);
    this.artifacts.delete(id);
    this.versions.delete(id);
    this.accessOrder = this.accessOrder.filter(aid => aid !== id);
    return existed;
  }

  /**
   * List artifacts with optional filtering
   */
  list(query: ArtifactQuery = {}): ArtifactListResponse {
    let artifacts = Array.from(this.artifacts.values());

    // Filter by conversation
    if (query.conversationId) {
      artifacts = artifacts.filter(a => a.conversationId === query.conversationId);
    }

    // Filter by type
    if (query.type) {
      artifacts = artifacts.filter(a => a.type === query.type);
    }

    // Sort by updatedAt descending
    artifacts.sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime());

    const total = artifacts.length;
    const offset = query.offset || 0;
    const limit = query.limit || this.config.defaultListLimit;

    artifacts = artifacts.slice(offset, offset + limit);

    return {
      artifacts,
      total,
      limit,
      offset,
    };
  }

  /**
   * Get version history for an artifact
   */
  getVersions(id: string): ArtifactVersion[] | undefined {
    return this.versions.get(id);
  }

  /**
   * Get a specific version of an artifact
   */
  getVersion(id: string, version: number): ArtifactVersion | undefined {
    const versions = this.versions.get(id);
    return versions?.find(v => v.version === version);
  }

  /**
   * Delete all artifacts for a conversation
   */
  deleteConversation(conversationId: string): number {
    let count = 0;
    for (const [id, artifact] of this.artifacts) {
      if (artifact.conversationId === conversationId) {
        this.delete(id);
        count++;
      }
    }
    return count;
  }

  /**
   * Get storage statistics
   */
  getStats(): StorageStats {
    const byType: Record<ArtifactType, number> = {
      code: 0,
      text: 0,
      markdown: 0,
      html: 0,
      json: 0,
      yaml: 0,
      xml: 0,
      csv: 0,
      image: 0,
      diagram: 0,
    };

    const byConversation: Record<string, number> = {};
    let totalVersions = 0;

    for (const artifact of this.artifacts.values()) {
      byType[artifact.type]++;
      byConversation[artifact.conversationId] = 
        (byConversation[artifact.conversationId] || 0) + 1;
    }

    for (const versions of this.versions.values()) {
      totalVersions += versions.length;
    }

    return {
      totalArtifacts: this.artifacts.size,
      totalVersions,
      byType,
      byConversation,
    };
  }

  /**
   * Clear all artifacts
   */
  clear(): void {
    this.artifacts.clear();
    this.versions.clear();
    this.accessOrder = [];
  }

  /**
   * Update LRU access order
   */
  private updateAccessOrder(id: string): void {
    this.accessOrder = this.accessOrder.filter(aid => aid !== id);
    this.accessOrder.push(id);
  }

  /**
   * Enforce maximum artifacts limit using LRU eviction
   */
  private enforceMaxArtifacts(): void {
    while (this.artifacts.size >= this.config.maxArtifacts && this.accessOrder.length > 0) {
      const oldestId = this.accessOrder.shift();
      if (oldestId) {
        this.artifacts.delete(oldestId);
        this.versions.delete(oldestId);
      }
    }
  }
}
