import express, { Request, Response, NextFunction } from 'express';
import { ArtifactEngine } from './artifact-engine';
import { 
  validateCreateRequest, 
  validateUpdateRequest,
  ArtifactQuery,
  isValidArtifactType 
} from './types';
import { loadConfig } from './config';

const config = loadConfig();
const app = express();
const engine = new ArtifactEngine(config);

app.use(express.json({ limit: config.maxContentSize }));

// Error handling middleware
app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
  console.error('Error:', err.message);
  res.status(500).json({ error: 'Internal server error' });
});

// Health check
app.get('/health', (req: Request, res: Response) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Create artifact
app.post('/artifacts', (req: Request, res: Response) => {
  if (!validateCreateRequest(req.body)) {
    return res.status(400).json({ error: 'Invalid request body' });
  }

  const artifact = engine.create(req.body);
  res.status(201).json(artifact);
});

// Get artifact
app.get('/artifacts/:id', (req: Request, res: Response) => {
  const artifact = engine.get(req.params.id);
  if (!artifact) {
    return res.status(404).json({ error: 'Artifact not found' });
  }
  res.json(artifact);
});

// Update artifact
app.put('/artifacts/:id', (req: Request, res: Response) => {
  if (!validateUpdateRequest(req.body)) {
    return res.status(400).json({ error: 'Invalid request body' });
  }

  const artifact = engine.update(req.params.id, req.body);
  if (!artifact) {
    return res.status(404).json({ error: 'Artifact not found' });
  }
  res.json(artifact);
});

// Delete artifact
app.delete('/artifacts/:id', (req: Request, res: Response) => {
  const deleted = engine.delete(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: 'Artifact not found' });
  }
  res.status(204).send();
});

// List artifacts
app.get('/artifacts', (req: Request, res: Response) => {
  const query: ArtifactQuery = {};

  if (typeof req.query.conversationId === 'string') {
    query.conversationId = req.query.conversationId;
  }

  if (typeof req.query.type === 'string' && isValidArtifactType(req.query.type)) {
    query.type = req.query.type;
  }

  if (typeof req.query.limit === 'string') {
    query.limit = parseInt(req.query.limit, 10);
  }

  if (typeof req.query.offset === 'string') {
    query.offset = parseInt(req.query.offset, 10);
  }

  const result = engine.list(query);
  res.json(result);
});

// Get artifact versions
app.get('/artifacts/:id/versions', (req: Request, res: Response) => {
  const versions = engine.getVersions(req.params.id);
  if (!versions) {
    return res.status(404).json({ error: 'Artifact not found' });
  }
  res.json(versions);
});

// Get specific version
app.get('/artifacts/:id/versions/:version', (req: Request, res: Response) => {
  const version = parseInt(req.params.version, 10);
  if (isNaN(version)) {
    return res.status(400).json({ error: 'Invalid version number' });
  }

  const artifactVersion = engine.getVersion(req.params.id, version);
  if (!artifactVersion) {
    return res.status(404).json({ error: 'Version not found' });
  }
  res.json(artifactVersion);
});

// Delete conversation artifacts
app.delete('/conversations/:conversationId/artifacts', (req: Request, res: Response) => {
  const count = engine.deleteConversation(req.params.conversationId);
  res.json({ deleted: count });
});

// Get stats
app.get('/stats', (req: Request, res: Response) => {
  const stats = engine.getStats();
  res.json(stats);
});

const PORT = config.port;

app.listen(PORT, () => {
  console.log(`Artifact Engine running on port ${PORT}`);
});

export { app, engine };
